// Japanese text on the voxel frame: small fixed-height 1-bit glyph sets
// generated by tools/make_glyphs.py (only the characters the effects use).
#pragma once

#include <cstdint>

#include "voxel_frame.hpp"

namespace gm {

struct JpGlyph {
  uint32_t codepoint;
  uint8_t width;
  const uint8_t* bits;  // `height` rows, MSB = leftmost pixel, rows byte-padded
};

struct JpFont {
  uint8_t height;
  uint16_t count;
  const JpGlyph* glyphs;  // sorted by codepoint
};

extern const JpFont kJpLarge;  // 24 px, Noto Serif JP Black, condensed (title cards)
extern const JpFont kJpSmall;  // 14 px, Noto Sans JP Bold (labels)

const JpGlyph* findGlyph(const JpFont& font, uint32_t codepoint);

// Draws UTF-8 text; ASCII falls back to the 3x5 HUD font (vertically centred).
// Characters missing from the font are skipped (their width still advances).
// Returns the advance in pixels (width for horizontal, height for vertical).
int drawJp(VoxelFrame& f, const JpFont& font, int z, int x, int y, const char* utf8, int spacing = 1,
           float intensity = 1.0f);
int drawJpVertical(VoxelFrame& f, const JpFont& font, int z, int x, int y, const char* utf8, int spacing = 1,
                   float intensity = 1.0f);
int measureJp(const JpFont& font, const char* utf8, int spacing = 1);

}  // namespace gm
